const fs = require('fs');
const data = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);

const N = data[0];
const costs = data.slice(1, 4).sort((a, b) => a - b);

let candies = N;
let count = 0;

for (let i = 0; i < 3; i++) {
  if (candies >= costs[i]) {
    candies -= costs[i];
    count++;
  } else {
    break;
  }
}

console.log(count);
